{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
  "name": "ajdershem-plugins",
  "description": "AJ Dershem's custom Claude Code plugins",
  "owner": {
    "name": "AJ Dershem"
  },
  "plugins": [
    {
      "name": "new-project-workflow",
      "description": "Scaffold new projects with production-ready infrastructure from day one. Interactive checklist with layered templates for any tech stack.",
      "version": "0.5.0",
      "author": {
        "name": "AJ Dershem"
      },
      "source": "./plugins/new-project-workflow",
      "category": "development"
    },
    {
      "name": "story-workflow",
      "description": "Three-phase story workflow: brainstorm and plan user stories, analyze queue and plan execution with dependency/conflict analysis, then dispatch subagents to implement with worktrees and integration verification.",
      "version": "1.1.0",
      "author": {
        "name": "AJ Dershem"
      },
      "source": "./plugins/story-workflow",
      "category": "development"
    },
    {
      "name": "maintain",
      "description": "Periodic maintenance and hygiene checks for CLAUDE.md, memory files, backlog, plugins, and stale artifacts. Auto-suggests when maintenance is overdue.",
      "version": "1.0.0",
      "author": {
        "name": "AJ Dershem"
      },
      "source": "./plugins/maintain",
      "category": "development"
    },
    {
      "name": "question-alerts",
      "description": "Multi-channel alerts (bell, macOS notification, statusline indicator) when Claude asks a question or waits for input via AskUserQuestion.",
      "version": "1.0.0",
      "author": {
        "name": "AJ Dershem"
      },
      "source": "./plugins/question-alerts",
      "category": "productivity"
    }
  ]
}
